-- 0009a — the five project briefs.
--
-- Generated by scripts/build-projects.cjs from content/projects/.
-- Edit the markdown there and re-run the script; do not edit this file.


insert into public.projects
  (module_id, position, slug, title, summary, brief_md, rubric_md)
select m.id,
       1,
       $md$data-clean$md$,
       $md$A messy file, cleaned$md$,
       $md$Take a real, dirty dataset and produce a clean one — plus a defence of every decision you made.$md$,
       $md$Find a genuinely messy public dataset. Government open data portals, Kaggle and data.gov.in are full of them; pick something with at least a few thousand rows, mixed types and real missing values. Do not use a tutorial dataset that is already clean.

**Build**

- `notebooks/` or `src/` — the cleaning, as a script or notebook that runs top to bottom
- `data/` — the raw file (or a link to it if it is large) and the cleaned output
- `README.md` — what the data is, what was wrong with it, and what you did

**Answer at least five questions** of your own about the data using `groupby` and a join, and show the output.

**The marked part** is the README section headed "Decisions". For every missing-value choice, every de-duplication rule and every row you dropped, say what you did and why. "Filled with the median" is not enough; "filled with the median because it is 3% of rows, missing at random, and the column is skewed" is.

Include the assertions that check your work — row counts after merges, ranges, uniqueness.$md$,
       $md$Scored out of 10.

- **Runs (2)** — the code executes end to end on a fresh checkout
- **Cleaning is real (2)** — types fixed, dates parsed unambiguously, near-duplicate text normalised
- **Decisions defended (3)** — every choice named and justified, not just performed
- **Checks present (1)** — assertions on row counts, ranges, uniqueness
- **Questions answered (1)** — five real questions, with grouping and a join
- **Readable (1)** — a README someone else could follow$md$
from public.modules m
where m.slug = 'agentic-ai'
on conflict (slug) do update
  set title = excluded.title,
      summary = excluded.summary,
      brief_md = excluded.brief_md,
      rubric_md = excluded.rubric_md,
      position = excluded.position;


insert into public.projects
  (module_id, position, slug, title, summary, brief_md, rubric_md)
select m.id,
       2,
       $md$model-train$md$,
       $md$A model you can defend$md$,
       $md$Train a small model properly: an honest split, everything inside a pipeline, and a metric you chose before you saw the score.$md$,
       $md$Use your cleaned dataset from Project 1, or another one. Pick a real question — will a student pass, will an order be late, what will this cost.

**Build**

- A scikit-learn `Pipeline` containing every transformation. No scaling or imputing outside it.
- An honest split. Time-ordered data gets a time-ordered split, not a random one.
- A baseline to beat — predicting the majority class, or the mean.
- Cross-validation, reported as mean and spread.

**Write, in the README, before the results section**: which metric you are optimising and why that one matters for this problem. Then the confusion matrix and the classification report.

**Say what you would need to trust this in production.** More data, a different metric, a fairness check, a human in the loop — whatever is actually true.$md$,
       $md$Scored out of 10.

- **No leakage (3)** — every transformation inside the pipeline, split before anything is fitted
- **Honest evaluation (2)** — a real held-out set, cross-validation with spread reported
- **Metric justified (2)** — chosen and defended before the results, and appropriate to the class balance
- **Baseline (1)** — something to beat, and it is beaten
- **Limits stated (1)** — what would be needed to trust it
- **Runs (1)** — executes end to end$md$
from public.modules m
where m.slug = 'agentic-ai'
on conflict (slug) do update
  set title = excluded.title,
      summary = excluded.summary,
